import { UserRepository } from '../repositories/user-repository.js';

const users = new UserRepository();

// Callback-style public API, backed by UserRepository.
// Two-argument then() so an exception thrown by the callback is never
// routed back into it as a second call.
function toCallback(promise, callback) {
  promise.then((value) => callback(null, value), (err) => callback(err));
}

export function findByEmail(email, callback) {
  toCallback(users.findActiveByEmail(email), callback);
}

export function isActive(email, callback) {
  findByEmail(email, (err, user) => {
    if (err) return callback(err);
    callback(null, Boolean(user));
  });
}

// Sets last_login_at to now on the active user with this email.
// Calls back with the updated user, or null if there is no active user.
export function recordLogin(email, callback) {
  findByEmail(email, (err, user) => {
    if (err) return callback(err);
    if (!user) return callback(null, null);
    toCallback(users.setLastLogin(user.id, new Date().toISOString()), callback);
  });
}

